		const PALETTE = {};
		for (const name of Object.keys(PALETTE_LIGHT)) PALETTE[name] = { light: PALETTE_LIGHT[name], dark: PALETTE_DARK[name] };

		const SCHEME_LABELS = { light: "朱砂 · 浅色", dark: "朱砂 · 深色" };

